import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.io.*;
import java.util.logging.*;

@WebServlet("/api/reports/*")
public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL"); // e.g. jdbc:postgresql://db:5432/analytics
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String pathInfo = req.getPathInfo();
        resp.setContentType("application/json");

        if ("/search".equals(pathInfo)) {
            handleSearch(req, resp);
        } else if ("/summary".equals(pathInfo)) {
            handleSummary(req, resp);
        } else {
            resp.setStatus(404);
            resp.getWriter().write("{\"error\":\"not found\"}");
        }
    }

    private void handleSearch(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String category = req.getParameter("category");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String sortCol = req.getParameter("sort");
        String limit = req.getParameter("limit");

        if (category == null || category.isEmpty()) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"category required\"}");
            return;
        }

        // Validate sort column against whitelist
        List<String> allowedSorts = Arrays.asList("created_at", "amount", "title", "id");
        if (sortCol == null || !allowedSorts.contains(sortCol)) {
            sortCol = "created_at";
        }

        // Validate limit
        int limitVal = 50;
        try { if (limit != null) limitVal = Math.min(Integer.parseInt(limit), 200); }
        catch (NumberFormatException e) { /* use default */ }

        // Build query - category is parameterized, sort is whitelisted
        String sql = "SELECT id, title, amount, created_at FROM reports " +
                     "WHERE category = ? AND created_at >= ? AND created_at <= ? " +
                     "ORDER BY " + sortCol + " DESC LIMIT " + limitVal;

        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, category);
            ps.setString(2, dateFrom != null ? dateFrom : "2020-01-01");
            ps.setString(3, dateTo != null ? dateTo : "2030-12-31");
            ResultSet rs = ps.executeQuery();
            resp.getWriter().write(resultSetToJson(rs));
        } catch (SQLException e) {
            log.warning("Search query failed: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"query failed\"}");
        }
    }

    private void handleSummary(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String groupBy = req.getParameter("group");
        String filterExpr = req.getParameter("filter");

        // The groupBy is used to build dynamic aggregation
        if (groupBy == null) groupBy = "category";

        // NOTE: filterExpr allows flexible server-side filtering for
        // the reporting dashboard's advanced mode
        String sql = "SELECT " + groupBy + ", COUNT(*) as cnt, SUM(amount) as total " +
                     "FROM reports";

        if (filterExpr != null && !filterExpr.isEmpty()) {
            sql += " WHERE " + filterExpr;
        }

        sql += " GROUP BY " + groupBy;

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {
            resp.getWriter().write(resultSetToJson(rs));
        } catch (SQLException e) {
            log.warning("Summary query failed: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"query failed\"}");
        }
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        StringBuilder sb = new StringBuilder("[");
        boolean first = true;
        while (rs.next()) {
            if (!first) sb.append(",");
            sb.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) sb.append(",");
                sb.append("\"").append(meta.getColumnLabel(i)).append("\":");
                Object val = rs.getObject(i);
                if (val instanceof Number) sb.append(val);
                else sb.append("\"").append(String.valueOf(val).replace("\"", "\\\"")).append("\"");
            }
            sb.append("}");
            first = false;
        }
        sb.append("]");
        return sb.toString();
    }
}
